def perform_operations(digits, k):
    n = len(digits)
    for _ in range(k):
        found = False
        for i in range(n - 1):
            if digits[i] == 4 and digits[i + 1] == 7:
                found = True
                if i % 2 == 0:
                    digits[i] = 4
                    digits[i + 1] = 4
                else:
                    digits[i] = 7
                    digits[i + 1] = 7
                break
        if not found:
            break
    return ''.join(map(str, digits))

